sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-18,right:18,top:18,bottom:-18,near:1,far:55});sun.shadow.bias=-.0003;sun.shadow.normalBias=.035;scene.add(sun);
