for(let i=0;i<35;i++){ex.fillStyle="rgba(255,248,226,0.14)";ex.beginPath();ex.ellipse(rand()*512,35+rand()*55,10+rand()*60,3+rand()*12,0,0,Math.PI*2);ex.fill();}
