[{u:-3.6,y:4.7},{u:.7,y:4.7},{u:-3.6,y:1.7},{u:.7,y:1.7}].forEach((h,i)=>houseWindow("rear window "+i,h.u,h.y,1.3,1.6,"x",back-.015,-1));
